<!-- Props: open?, themes?, historyAdventures?, themeId?; Emits: update:open, update:themeId; Slots: —; Exposed: — -->
<script setup lang="ts">
import { computed, watch, onBeforeUnmount, ref } from 'vue'
import { api } from '$lib/api'
import { HISTORY_XP_GLOBAL_THEME_ID, historyXpThemeId } from '$lib/historyXp'
import { MIX_THEME_ID } from '$lib/themes'
import type { StoryAdventure } from '$lib/historyAdventures'
import type { LeaderboardEntry, LeaderboardSegment, Theme } from '$lib/types'
const props=withDefaults(defineProps<{open?:boolean;themes?:Theme[];historyAdventures?:StoryAdventure[];themeId?:string}>(),{open:false,themes:()=>[],historyAdventures:()=>[],themeId:''})
const emit=defineEmits<{ 'update:open':[value:boolean];'update:themeId':[value:string] }>()
const scope=ref<'global'|'theme'>('theme'),segment=ref<LeaderboardSegment>('registered'),rows=ref<LeaderboardEntry[]>([]),loading=ref(false),dialog=ref<HTMLElement>()
const quizThemes=computed(()=>props.themes.filter(t=>t.id!==MIX_THEME_ID));const historyIds=computed(()=>[...(props.historyAdventures.length?[HISTORY_XP_GLOBAL_THEME_ID]:[]),...props.historyAdventures.map(a=>historyXpThemeId(a.id))])
const themeOptions=computed(()=>[...quizThemes.value.map(t=>({id:t.id,label:`${t.emoji} ${t.name}`,group:'quiz'})),...(props.historyAdventures.length?[{id:HISTORY_XP_GLOBAL_THEME_ID,label:'🧭 Toutes les aventures',group:'history'}]:[]),...props.historyAdventures.map(a=>({id:historyXpThemeId(a.id),label:`${a.emoji?`${a.emoji} `:''}${a.title}`,group:'history'}))])
const themeLabel=computed(()=>quizThemes.value.find(t=>t.id===props.themeId)?.name??(props.themeId===HISTORY_XP_GLOBAL_THEME_ID?'À la trace de l’histoire (toutes aventures)':props.historyAdventures.find(a=>historyXpThemeId(a.id)===props.themeId)?.title??props.themeId))
function close(){emit('update:open',false)}function keydown(e:KeyboardEvent){if(e.key==='Escape'&&props.open)close()}
let controller:AbortController|undefined
async function loadRows(){if(!props.open)return;if(scope.value==='theme'&&!props.themeId.trim()){rows.value=[];return}controller?.abort();controller=new AbortController();loading.value=true;try{const data=await api<{leaderboard?:LeaderboardEntry[]}>('/leaderboard',{query:{scope:scope.value,segment:segment.value,theme:scope.value==='theme'?props.themeId:undefined},signal:controller.signal});rows.value=data.leaderboard??[]}catch(e){if(!(e instanceof DOMException&&e.name==='AbortError'))rows.value=[]}finally{loading.value=false}}
watch(()=>[props.open,scope.value,segment.value,props.themeId] as const,()=>{void loadRows()},{immediate:true})
watch(()=>[props.open,scope.value,quizThemes.value,historyIds.value] as const,()=>{if(!props.open||scope.value!=='theme')return;const options=themeOptions.value.map(t=>t.id);if(options.length&&(!props.themeId||!options.includes(props.themeId)))emit('update:themeId',options[0]!)},{immediate:true})
watch(()=>props.open,value=>{if(typeof document==='undefined')return;if(value){document.addEventListener('keydown',keydown);requestAnimationFrame(()=>dialog.value?.focus())}else document.removeEventListener('keydown',keydown)},{immediate:true})
onBeforeUnmount(()=>{controller?.abort();document.removeEventListener('keydown',keydown)})
function fmt(m:number|null|undefined){if(m==null||!Number.isFinite(m))return '—';return m>=1000?`${(m/1000).toLocaleString('fr-FR',{maximumFractionDigits:1})} km`:`${Math.round(m).toLocaleString('fr-FR')} m`}
</script>
<template>
<Teleport to="body"><div v-if="open" class="modal-backdrop" role="presentation" @click.self="close"><section ref="dialog" class="modal" role="dialog" aria-modal="true" aria-labelledby="lb-modal-title" tabindex="-1" @keydown.esc.stop="close"><header class="modal-header"><div><h2 id="lb-modal-title">Classements</h2><p class="subtle"><strong>Inscrits</strong> : XP durable, tous thèmes ou par thème. <strong>Visiteurs (jour UTC)</strong> : sessions invité et XP gagnée aujourd’hui par les comptes enregistrés.</p></div><button type="button" class="btn btn-ghost btn-sm" @click="close">Fermer</button></header><div class="modal-body leaderboard-controls"><div class="segmented"><button type="button" :class="{active:scope==='global'}" @click="scope='global'">Global</button><button type="button" :class="{active:scope==='theme'}" @click="scope='theme'">Par thème</button></div><label v-if="scope==='theme'" class="field"><span class="sr-only">Thème ou aventure</span><select :value="themeId" @change="emit('update:themeId',($event.target as HTMLSelectElement).value)"><optgroup v-if="quizThemes.length" label="Thèmes quiz"><option v-for="t in quizThemes" :key="t.id" :value="t.id">{{t.emoji}} {{t.name}}</option></optgroup><optgroup v-if="historyAdventures.length" label="À la trace de l’histoire"><option v-for="opt in themeOptions.filter(x=>x.group==='history')" :key="opt.id" :value="opt.id">{{opt.label}}</option></optgroup></select></label><div class="segmented"><button type="button" :class="{active:segment==='registered'}" @click="segment='registered'">Inscrits</button><button type="button" :class="{active:segment==='guest'}" @click="segment='guest'">Visiteurs (jour UTC)</button></div><p class="subtle">{{scope==='global'?'Classement sur l’XP totale (quiz + histoire)':historyIds.includes(themeId)?`Mode histoire : ${themeLabel} — XP sur cette sélection uniquement`:`Thème : ${themeLabel} — XP sur ce thème uniquement`}}{{segment==='guest'?' (jour UTC)':''}}. Précision moyenne : distance moyenne au lieu correct.</p><div class="between"><strong class="subtle">Top 30</strong><button type="button" class="btn btn-ghost btn-sm" @click="loadRows">Actualiser</button></div><div v-if="loading" class="loading"><span class="spinner"/>Chargement…</div><p v-else-if="!rows.length" class="empty">Aucun score pour ce filtre. Joue une manche !</p><div v-else class="leaderboard-table"><div class="leaderboard-row leaderboard-row--head"><span>Joueur</span><span>Préc. moy.</span><span>XP</span></div><ol><li v-for="(row,i) in rows" :key="row.pseudo+i" class="leaderboard-row"><span><b>#{{i+1}}</b> {{row.pseudo}}</span><span :title="'Distance moyenne au lieu correct (plus bas = plus précis)'">{{fmt(row.avgDistanceM)}}</span><strong>{{row.xp.toLocaleString('fr-FR')}} XP</strong></li></ol></div></div></section></div></Teleport>
</template>
<style scoped>.modal-header{align-items:flex-start}.modal-header>div{display:grid;gap:7px}.modal-header .subtle{max-width:670px;font-size:12px}.leaderboard-controls{display:grid;gap:14px}.leaderboard-table{display:grid;gap:5px}.leaderboard-table ol{display:grid;gap:6px;margin:0;padding:0;list-style:none}.leaderboard-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:12px;align-items:center;padding:8px 10px;border-radius:9px;background:var(--surface-2);font-size:13px}.leaderboard-row span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.leaderboard-row b{color:var(--primary)}.leaderboard-row strong{color:#92400e;text-align:right}.leaderboard-row--head{background:none;color:var(--muted);font-size:10px;text-transform:uppercase}.leaderboard-row--head span:not(:first-child){text-align:right}</style>
